UPDATE payment_refund
SET status = 'PROCESSING', attempt_count = attempt_count + 1,
    processing_owner = #{owner}, processing_until = #{until}, updated_at = #{now}
WHERE refund_id = #{refundId}
  AND ((status IN ('CREATED', 'FAILED') AND next_attempt_at <= #{now})
    OR (status = 'PROCESSING' AND processing_until < #{now}))
